TRAY_ICONS = {'0a': '', '0i': '', '1a': '', '1i': '', '2a': '', '2i': '', '3a': '', '3i': '', '4a': '', '4i': '', 'tool': ''}   # 预渲染托盘图标 (base64 ICO, 见 tray._embedded_icons)
