def _load(name, src):
    mod = types.ModuleType(name)
    sys.modules[name] = mod
    mod.__file__ = os.path.join(os.path.dirname(os.path.abspath(__file__)), name + ".py")
    exec(compile(src, name + ".py", "exec"), mod.__dict__)
    return mod
import threading as _threading
_EAGER = ("win", "hook", "engine")   # 装钩子之前必须就绪的模块
_PENDING = {}
_lazy_lock = _threading.RLock()      # RLock: 模块 exec 期间可能再触发别的懒模块
def _load_into(name, mod):
    with _lazy_lock:
        src = _PENDING.pop(name, None)
        if src is None:
            return
        mod.__dict__.pop("__getattr__", None)   # 去掉懒加载器, 再 exec 真源码
        exec(compile(src, name + ".py", "exec"), mod.__dict__)
def _lazy(name):
    mod = types.ModuleType(name)
    mod.__file__ = os.path.join(os.path.dirname(os.path.abspath(__file__)), name + ".py")
    _PENDING[name] = MODULES[name]
    def _getattr(attr, _n=name, _m=mod):
        _load_into(_n, _m)
        return getattr(_m, attr)
    mod.__getattr__ = _getattr            # PEP 562 模块级 __getattr__
    sys.modules[name] = mod
    return mod
for _n in MODULES:
    if _n in _EAGER:
        _load(_n, MODULES[_n])
    else:
        _lazy(_n)
